_BASE_AGENT = _BASE_NS["agent"]
_OPERATOR = _OP_NS['sell_impact_reorder']
_OPERATOR_CONFIGURATION = {'sell_impact_demand_alpha': 0.25}

def _find_tape_hooks(namespace):
    seen = set()
    while isinstance(namespace, dict) and id(namespace) not in seen:
        seen.add(id(namespace))
        selector = namespace.get("_selected_tape")
        impl = namespace.get("_IMPL")
        if callable(selector) or impl is not None:
            return selector, impl
        namespace = namespace.get("_BASE_NS")
    return None, None

_PARENT_TAPE_SELECTOR, _PARENT_IMPL = _find_tape_hooks(_BASE_NS)

def _selected_tape(observation):
    if callable(_PARENT_TAPE_SELECTOR):
        return _PARENT_TAPE_SELECTOR(observation)
    if _PARENT_IMPL is None:
        return None
    try:
        player = int(observation.get("player", 0))
        step = int(observation.get("step", 0))
        native = _PARENT_IMPL.chassis.players[player]
        route = 2 if step >= 648 else native.get("route", 0)
        return SimpleNamespace(
            route_id=f"local-best-native-{route}",
            actions=tuple(_PARENT_IMPL.chassis.routes[route]),
        )
    except Exception:
        return None

def agent(observation, configuration=None):
    action = _BASE_AGENT(observation, configuration)
    tape = (_selected_tape(observation)
            if 'sell_impact_reorder' in {"market_queue_lockstep", "racegate_reservation",
                                  "opponent_front_run", "adaptive_market_tape_guard",
                                  "sale_advance", "sale_advance_policy",
                                  "sale_advance_pressure", "budget_guard",
                                  "room_guard", "supply_prefetch",
                                  "sell_impact_reorder"}
            else None)
    return _OPERATOR(observation, action, _OPERATOR_CONFIGURATION, tape)





# v46 integration, Omer Faruk Merey, 2026. Apache-2.0.
# Bound late seed purchases by remaining useful planting opportunities; remove
# only provably dead market orders using the inherited exact field simulator.
_V46_PARENT = agent
_V46_CORE = _BASE_NS
while "_BASE_NS" in _V46_CORE:
    _V46_CORE = _V46_CORE["_BASE_NS"]
_V46_PLANTS = [0] * 720
for _v46_t in range(670, 647, -1):
    _v46_action = _V46_CORE["_IMPL"].chassis.routes[2][_v46_t + 1]
    _v46_units = [_v46_action.get("farmer") or ["PASS"], *(_v46_action.get("hands") or [])]
    _V46_PLANTS[_v46_t] = _V46_PLANTS[_v46_t + 1] + sum(
        len(command) > 1 and command[0] == "PLANT" and command[1] in ("WHEAT", "CARROT")
        for command in _v46_units
    )


def _v46_finish(observation, action):
    step = int(observation["step"])
    orders = action.get("market") or []
    if not orders:
        return action
    _, private = _V46_CORE["_r127_fields"](observation, action)
    stock = dict(private["shed"])
    seeds = dict(private["seeds"])
    seat = int(observation["player"])
    native = _V46_CORE["_IMPL"].chassis.players[seat]
    remaining = _V46_PLANTS[step] if 648 <= step < 671 else 0
    if step < 671:
        remaining += sum(
            len(command) > 1 and command[0] == "PLANT" and command[1] in ("WHEAT", "CARROT")
            for queue in native["pending"].values() for _, command in queue
        )
    unknown = set()
    out = []
    for raw in orders[:10]:
        order = list(raw)
        if step >= 648 and len(order) >= 3 and order[0] == "BUY_SEED":
            item = order[1]
            requested = max(0, int(order[2]))
            # All crops need at least two dawns. A purchase at hour 23 of day
            # 27 cannot be planted until day 28, too late to produce by 718.
            allowance = 0 if step >= 671 else remaining if item in ("WHEAT", "CARROT") else requested + seeds.get(item, 0)
            quantity = min(requested, max(0, allowance - seeds.get(item, 0)))
            seeds[item] = seeds.get(item, 0) + quantity
            if item == "CARROT" and quantity < requested:
                carrot = _V46_CORE["_CA_STATE"].get(seat)
                if carrot is not None:
                    carrot["spare_carrot"] = max(0, carrot.get("spare_carrot", 0) - requested + quantity)
            order = ["BUY_SEED", item, quantity] if quantity else []
        if not order or (len(order) >= 3 and int(order[2]) <= 0):
            continue
        if order[0] == "BUY_LAND" and len(observation["farms"][seat]["unlocked_quadrants"]) >= 4:
            continue
        if len(order) >= 3:
            op, item, quantity = order[0], order[1], int(order[2])
            if op == "SELL" and item not in unknown:
                sold = min(quantity, stock.get(item, 0))
                if sold <= 0:
                    continue
                stock[item] -= sold
            elif op in ("BUY_PRODUCT", "BUY_ANIMAL"):
                # Purchases depend on cash, capacity and simultaneous
                # opponent orders. A later sale is not provably dead.
                unknown.add(item)
        out.append(order)
    if out == orders:
        return action
    action = dict(action, market=out)
    race = _V46_CORE["_RACE_STATE"].get(seat)
    if race is not None and race.get("step") == step and race.get("prev_action") is not None:
        race["prev_action"] = action
    return action


def kaggriculture_v46(observation, configuration=None):
    action = _V46_PARENT(observation, configuration)
    standard = configuration is None or all(
        configuration.get(key, value) == value
        for key, value in (("episodeSteps", 720), ("boardSize", 10), ("turnsPerDay", 24),
                           ("shedCapacity", 100), ("maxMarketOrdersPerTurn", 10))
    )
    return _v46_finish(observation, action) if standard else action


agent = kaggriculture_v46
